MAT = dict(id="mat", n="马太福音", ab="太", en="Matthew", ic="👑", col="#f5b942", ch=28, fn="matthew.html",
 port="君王弥赛亚", sym="👤 人（耶柔米传统：从家谱“人”的世系开始）", aud="犹太读者", stamp="“这是要应验……”",
 au="使徒马太（又名利未），原是迦百农的税吏（{{太9:9}}；{{可2:14}}）；帕皮亚、爱任纽等早期教父一致归于他",
 date="约主后 50–60 年代（圣殿被毁之前）", place="巴勒斯坦或叙利亚的安提阿",
 to="以犹太基督徒为主、同时向外邦宣教的教会", fr="antioch", dest="jerusalem", acts="太1:1；太28:18-20",
 kw="天国", core="拿撒勒人耶稣就是亚伯拉罕与大卫的子孙、应验律法和先知的弥赛亚君王；天国已在祂里面临近；祂建立新以色列——教会，并差遣门徒使万民作门徒。",
 kv="太5:17", mn="一家谱（王的出身）· 五篇讲论（山·差·比·会·末）· 十余次“应验” · 一个大使命",
 bg="主后一世纪中叶，信耶稣的犹太人与会堂之间的张力日渐加剧：被钉十字架的拿撒勒人怎能是弥赛亚？外邦人大量归入教会，又让人追问神对以色列的应许是否落空。马太以犹太人熟悉的方式回答：从**亚伯拉罕与大卫的家谱**开始（{{太1:1}}），反复说明耶稣的出生、居所、事工、受难都“是要应验主藉先知所说的话”，并把耶稣的教训编成**五大篇讲论**，像新的“摩西五经”交给教会。全书引用和暗指旧约六十次以上，是四福音中最“犹太”的一卷，却以**万民**作结。",
 cul="**犹太—叙利亚文化圈**：家谱是身份与继承权的凭据；拉比以“你们听见有话说……只是我告诉你们”的方式讲律法；“天国”一词（约 32 次）体现犹太人敬畏神名、以“天”代称神的习惯。**税吏**为罗马与希律收税，被视为卖国者与罪人，马太自己就是蒙召的税吏。叙利亚的安提阿是犹太人与外邦人共处的大城，正适合一本既尊重律法又面向万国的福音书。",
 why=["犹太人质疑：被钉十字架的人怎能是弥赛亚？","会堂排斥信耶稣的犹太人，信徒需要确据","外邦人涌入，需要说明神对万国的计划（{{太28:19}}）","教会需要一本可教导、可背诵的门徒手册（五篇讲论）"],
 ol=[("1–2","王的出身：家谱、降生、东方博士、逃往埃及",2),("3–4","王的预备：约翰、受洗、试探、开始传道",2),("5–7","第一讲：登山宝训——天国子民的义",3),("8–10","十个神迹与第二讲：差遣十二使徒",3),("11–13","反对加剧与第三讲：天国的比喻",3),("14–18","彼得认信与第四讲：天国群体（教会）生活",5),("19–25","上耶路撒冷与第五讲：橄榄山讲论（末世）",7),("26–28","王的受难、复活与大使命",3)],
 bt="马太福音第一句「亚伯拉罕的后裔，大卫的子孙，耶稣基督的家谱」（{{太1:1}}），用“家谱/起源”一词回响创世记的“这是……的后代”，宣告**新创造**的开端。耶稣重演以色列的历史：被带下埃及又从埃及被召出（{{太2:15}}，引何11:1）、经过水（受洗）、在旷野受试探四十天并三次引用申命记回答（{{太4:4}}）、上山颁布天国之律（5–7 章，**新摩西**）、拣选十二门徒（**新以色列**十二支派）。祂是“比圣殿更大的”（{{太12:6}}）、“比所罗门更大的”（{{太12:42}}）。全书以“以马内利”开头（{{太1:23}}），以“我就常与你们同在”收尾（{{太28:20}}）——**神与人同在**是从伊甸园、会幕、圣殿直到新耶路撒冷的整本圣经主线。",
 ct="==亚伯拉罕之约==（万国因你的后裔得福，创22:18）与==大卫之约==（永远的王位，撒下7）在耶稣身上会合：家谱以这两位立约的人为纲。最后晚餐中耶稣说“这是我立约的血，为多人流出来，使罪得赦”（{{太26:28}}），把出埃及记 24 章的立约之血与耶利米书 31 章的新约赦罪连在一起。大使命中“奉父、子、圣灵的名给他们施洗”（{{太28:19}}），使洗礼成为新约的入约记号；耶稣又说“让小孩子到我这里来”（{{太19:14}}），改革宗据此与旧约割礼的连续性，为信徒的婴孩施洗。天国的钥匙（{{太16:19}}；{{太18:18}}）交给教会，透过传道与纪律开关天国。",
 key=["**天国已经临近**：君王已来，国度以“已然—未然”的方式降临（{{太4:17}}；{{太13}}）","**耶稣成全律法**：不是废掉，而是成全（{{太5:17}}），并把律法的真义带回人心（5:21-48）","**应验的弥赛亚**：十余次“应验”套语，证明旧约整体指向祂","**教会与纪律**：建立在认信“你是基督，是永生神的儿子”之上（{{太16:16}}；18 章）","**大使命**：天上地下所有的权柄都赐给祂，所以要使万民作门徒（{{太28:18-20}}）"],
 hard=[("!!“我来……乃是要成全”：旧约律法今天还有效吗？（5:17-20）!!","改革宗把摩西律法分为**道德律、礼仪律、民事律**：礼仪律的影儿在基督里已经成全而停止（BC 25），民事律随以色列国体结束，只其中的公义原则仍有教导意义；道德律（十诫）是神圣洁的旨意，仍是信徒感恩生活的准则（HC 3 部分；WCF 19）。耶稣“成全”律法：以完全的顺服满足它、以代赎承担它的咒诅、以圣灵把它写在心上。"),
  ("!!“我要把我的教会建造在这磐石上”（16:18）：磐石是彼得吗？!!","耶稣用“彼得（石头）”与“磐石”作文字游戏；许多改革宗释经家（包括加尔文）认为磐石指彼得所认信的基督，也有人认为指**作为认信者与使徒代表的彼得**。即便取后者，经文也只说教会建立在使徒的根基上（{{弗2:20}}），丝毫没有“教皇继承”的观念；钥匙权在 18:18 也交给整个教会。"),
  ("!!橄榄山讲论（24 章）讲的是主后 70 年还是主的再来？!!","门徒问了两个问题：圣殿何时被毁、主再来与世界末了有什么预兆（{{太24:3}}）。耶稣以**先知性的透视**回答：耶路撒冷的审判（主后 70 年，“这世代还没有过去”）是末日审判的预演与保证；24:36 以后转向“那日子、那时辰没有人知道”。改革宗多持此“近景—远景”读法，避免把全章只放在过去或只放在未来。"),
  ("!!“他的血归到我们和我们的子孙身上”（27:25）是否支持反犹？!!","绝不。这是众人自己的咒诅性宣告，马太记下它显明以色列领袖的弃绝；但同一“血”在 26:28 是“为多人流出来，使罪得赦”。初期教会的使徒全是犹太人，彼得在五旬节向同一批人传悔改赦罪（徒2:36-41）。基督徒的回应是为以色列祷告、传福音，而非仇恨。")],
 conf=[("hc",31),("bc",18,"因此，他实在是我们的以马内利，即神与我们同在（太1:23）。"),("hc",19),("bc",34,"出于这个原因，神吩咐说一切属他的人都要用清水受洗归入圣父、圣子、圣灵的名（参见太28:19）。"),("hc",83),("hc",123)],
 sermon=("/sermons/heidelberg-catechism/lord-day-48","基督的传道决定了教会的祷告！基督说：天国近了。天国就要临到了，因此我们祷告说：愿你的国降临！"),
 app=["用登山宝训检验心：不只问做了什么，更问心里如何（5:21-48）。","每次背主祷文（6:9-13），把“愿你的国降临”变成每天的优先次序。","在教会中实行 18:15-17 的挽回步骤，不在背后议论。","大使命不是少数人的职业：在家庭、职场“使人作门徒”，并支持宣教。"],
 ang={"历史":"写给与会堂分离中的犹太基督徒群体","文学":"五篇讲论 + 叙事交替；“耶稣讲完了这些话”五次为分界","神学":"弥赛亚论、天国论、教会论、律法的成全","牧养":"门徒训练手册：义、使命、饶恕、儆醒"},
 uniq=["东方博士、逃往埃及、伯利恒屠婴（2 章）","登山宝训的完整版（5–7 章）","彼得行海面（14:28-31）","天国钥匙与“教会”一词（16:18；18:17）","葡萄园工人、十童女、按才干受托、绵羊山羊（20；25 章）","犹大的结局、彼拉多洗手、看守坟墓（27 章）","大使命（28:16-20）"])

MRK = dict(id="mrk", n="马可福音", ab="可", en="Mark", ic="🦁", col="#ff6b8b", ch=16, fn="mark.html",
 port="受苦的仆人", sym="🦁 狮子（耶柔米传统：以“旷野有人声喊着”开头）", aud="罗马外邦读者", stamp="“立刻”",
 au="约翰马可（{{徒12:12}}；{{徒13:13}}；{{西4:10}}），彼得称他为“我儿子”（{{彼前5:13}}）；帕皮亚记载马可是彼得的“翻译者”，忠实记下彼得所讲",
 date="约主后 55–65 年（多数学者认为是最早成书的福音书）", place="罗马",
 to="罗马的外邦信徒（经文解释犹太习俗、翻译亚兰语、使用拉丁词）", fr="rome", dest="rome", acts="可1:1；可10:45",
 kw="仆人", core="神的儿子耶稣以权能宣告神的国，却走十字架的路：“人子来……乃是要服事人，并且要舍命作多人的赎价”；跟从祂就是舍己、背起十字架。",
 kv="可10:45", mn="起头（1:1）→ 立刻！→ “这到底是谁？”（4:41）→ 彼得认信（8:29）→ 三次受难预言 → 百夫长认信（15:39）→ 空坟",
 bg="主后 60 年代的罗马：主后 64 年大火后尼禄迫害基督徒，彼得与保罗相继殉道。亲眼见过主的使徒渐渐离世，教会需要把**彼得的见证**写下来；受逼迫的信徒更需要明白：弥赛亚本身就是受苦的，跟从祂也必背十字架（{{可8:34}}）。马可以快速、生动、动作密集的笔法写成全书，几乎一半篇幅放在耶路撒冷的最后一周——被称为「带着长序言的受难记」。",
 cul="**罗马城文化**：马可为外邦读者解释洗手礼与洁净规条（{{可7:3-4}}），翻译亚兰语（“大利大古米”5:41；“以罗伊，以罗伊，拉马撒巴各大尼”15:34），用拉丁借词与罗马币值说明（{{可12:42}}）。“福音”一词在帝国宣传中指皇帝登基或得胜的“好消息”，马可一开头便宣告真正的“**神的儿子**耶稣基督福音”（{{可1:1}}）；全书最后，罗马百夫长说“这人真是神的儿子”（{{可15:39}}）——帝国的士兵对着十字架认信。",
 why=["使徒一代渐渐离世，需要写下彼得的见证","罗马信徒面对逼迫：受苦与跟从的意义","外邦读者需要简明有力、以行动为主的耶稣故事","纠正只要能力、不要十字架的弥赛亚观（8:31-33）"],
 ol=[("1:1-13","起头：施洗约翰、受洗、试探",1),("1:14–3:6","加利利的权能：赶鬼、医病、赦罪、安息日之争",3),("3:7–6:6","比喻与神迹：“这到底是谁？”",4),("6:7–8:26","走向外邦地区：喂饱众人、行在海面、门徒仍不明白",3.5),("8:27–10:52","转折：彼得认信、三次受难预言、作门徒的代价",4),("11–13","耶路撒冷：骑驴进城、洁净圣殿、辩论、橄榄山讲论",3),("14–15","受难：受膏、最后晚餐、客西马尼、审判、十字架",3),("16","空坟：“他已经复活了”",1)],
 bt="“神的儿子，耶稣基督福音的起头”（{{可1:1}}）回响“起初神创造天地”。开篇引用以赛亚与玛拉基（1:2-3），宣告以赛亚预言的**新出埃及**开始了：耶和华要亲自在旷野开路回到锡安。耶稣受洗时“天裂开了”（{{可1:10}}，回应赛64:1“愿你裂天而降”），受死时“殿里的幔子从上到下裂为两半”（{{可15:38}}）——两次“裂开”首尾呼应：神来到人间，人得以进到神面前。“人子”取自但以理书 7 章的荣耀者（{{可14:62}}），“赎价”与“多人”取自以赛亚书 53 章的受苦仆人（{{可10:45}}）：马可把这两幅旧约图像合在一个人身上。",
 ct="凶恶园户的比喻（{{可12:1-12}}）以以赛亚书 5 章的葡萄园为背景：以色列领袖违背圣约、杀害先知与“爱子”，约的咒诅临到他们，葡萄园要“转给别人”——但房角的头块石头正是被弃的那一位。最后晚餐：“这是我立约的血，为多人流出来的”（{{可14:24}}），==新约是以中保的血坚立的==。耶稣定义新的立约家庭：「凡遵行神旨意的人，就是我的弟兄姐妹和母亲了」（{{可3:35}}）。祂抱着小孩子为他们祝福（{{可10:16}}），显明神的约也包括儿女。",
 key=["**“立刻”**：约 40 次，节奏急促——君王的行动不容迟延","**弥赛亚的秘密**：耶稣常吩咐不要张扬，直到十字架才显明祂是怎样的基督","**三次受难预言**（8:31；9:31；10:33-34），门徒三次误解，耶稣三次教导舍己","**门徒的失败与恢复**：彼得三次不认主，复活信息却特别点名“和彼得”（{{可16:7}}）","**十字架是认信的高峰**：百夫长在耶稣断气时认信（15:39）"],
 hard=[("!!马可福音 16:9-20 是原文吗？!!","最早、最可靠的两部抄本（西乃抄本、梵蒂冈抄本）结束于 16:8，许多教父也知道这一点；和合本以括号标示。改革宗学者多认为较长结尾是早期教会附加的摘要，内容大多可在其他福音书与使徒行传中找到根据。原则：**不可单凭这段建立教义或实践**（如手拿蛇、喝毒物），但它不影响任何基本教义。"),
  ("!!“那日子、那时辰……子也不知道”（13:32）：子不是全知的神吗？!!","这正是基督**神人二性**的奥秘：按神性，子与父同等、无所不知；按人性，祂在降卑中有真实的人的知识与成长（{{路2:52}}）。BC 19 说二性在一个位格里“各有其独特的属性”，人性“是有限的”。亚他那修信经也说：“以其神性，他与父同等，以其人性，他低于父。”"),
  ("!!为什么耶稣常叫人不要张扬（弥赛亚秘密）？!!","二十世纪初批判学者（弗雷德）认为这是教会后来编造的；正统解读：①避免群众把祂当作政治弥赛亚；②祂的身份只有在十字架与复活之后才能被正确理解（{{可9:9}}）；③祂按父所定的“时候”行事。秘密在 14:62 由耶稣在公会前亲自揭开。")],
 conf=[("hc",37),("bc",19,"正因如此，我们宣告基督是真神，也是真人。他是真神，为要藉着他的大能胜过死亡；他也是真人，所以才能以他软弱的肉体为我们受死。"),("dort",2,3),("hc",40),("hc",44),("dort",2,2)],
 sermon=("/sermons/heidelberg-catechism/lord-day-48","他写到：“耶稣来到加利利，宣传神的福音， 说：‘日期满了，神的国近了。你们当悔改，信福音。’”（可1:14,15）。"),
 app=["当你只想要“能力的耶稣”时，回到 8:34：舍己、背十字架。","失败的门徒仍有路：读 14:72 与 16:7，带着眼泪回到复活的主面前。","服事别人不是降格，而是像主（10:42-45）。","在苦难与逼迫中，十字架后面一定有空坟。"],
 ang={"历史":"罗马教会在逼迫前后收到的彼得见证","文学":"“三明治”结构（如 5:21-43；11:12-25）、急促的现在式叙事","神学":"基督论（神的儿子 + 受苦的人子）、门徒论","牧养":"苦难中的跟从与失败后的恢复"},
 uniq=["撒种长大的比喻（4:26-29）","医治耳聋舌结的人（7:31-37）","伯赛大分两步医好瞎子（8:22-26）","赤身逃走的少年人（14:51-52），传统认为是马可自己","“安息日是为人设立的”（2:27）"])
